static int dpaa_eth_init_ports ( struct mac_device * mac_dev , struct dpaa_bp * bp , struct fm_port_fqs * port_fqs , struct dpaa_buffer_layout * buf_layout , struct device * dev ) { struct fman_port * rxport = mac_dev -> port [ RX ] ; struct fman_port * txport = mac_dev -> port [ TX ] ; int err ; err = dpaa_eth_init_tx_port ( txport , port_fqs -> tx_errq , port_fqs -> tx_defq , & buf_layout [ TX ] ) ; err = dpaa_eth_init_rx_port ( rxport , bp , port_fqs -> rx_errq , port_fqs -> rx_defq , port_fqs -> rx_pcdq , & buf_layout [ RX ] ) ; return err ; } 